func TestHashPasswords(t *testing.T) {
    // Test case with two identical passwords should produce different hashes due to unique salts
    usernames := []string{"user1", "user2"}
    passwords := []string{"password123", "password123"}
    count := 2

    result := hashPasswords(count, usernames, passwords)

    // Check that salts are different
    if result[0][0] == result[1][0] {
        t.Error("Salts for identical passwords should be different")
    }

    // Check that hashes are different due to different salts
    if result[0][1] == result[1][1] {
        t.Error("Hashes for identical passwords with different salts should be different")
    }
}

