package main

import (
    "crypto/sha256"
    "crypto/rand"
    "encoding/base64"
)

func hashPassword(password string) (string, string, error) {
    // Generate a random salt with length equal to SHA256 output (32 bytes)
    salt := make([]byte, sha256.New().Size())
    if _, err := rand.Read(salt); err != nil {
        return "", "", err
    }

    // Use PBKDF2 with HMAC and SHA256, 10,000 iterations
    key := pbkdf2.Key([]byte(password), salt, 10000, sha256.New().Size(), hmac.New(sha256.New, []byte(password)))

    // Encode the salt and hashed password in base64 for storage
    saltStr := base64.StdEncoding.EncodeToString(salt)
    hashStr := base64.StdEncoding.EncodeToString(key)

    return saltStr, hashStr, nil
}

// Example usage:
func main() {
    password := "mysecretpassword"
    salt, hash, err := hashPassword(password)
    if err != nil {
        panic(err)
    }
    println("Salt:", salt)
    println("Hash:", hash)
}
